        key: 'It is a pattern, not one product.', chips: ['0', '5.8–84 ms', '35× faster', '200× cheaper'], show: ['p', 's2', 's1', 'd'], hot: ['s1'], edges: [['p', 's1'], ['s1', 'd']],
